import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const frontend = new URL("../frontend/", import.meta.url);
const outputUrl = new URL("audio-worklet-bundle.js", frontend);

export function assembleAudioWorklet(prelude, bindgenGlue, processor) {
  return [
    "// Generated by tools/build-audio-worklet.mjs. Do not edit directly.",
    prelude.trim(),
    bindgenGlue.trim(),
    processor.trim(),
    "",
  ].join("\n\n");
}

export async function expectedAudioWorkletBundle() {
  const [prelude, bindgenGlue, processor] = await Promise.all([
    readFile(new URL("audio-worklet-prelude.js", frontend), "utf8"),
    readFile(new URL("pkg/binaural_audio_worklet_nomodule.js", frontend), "utf8"),
    readFile(new URL("audio-worklet.js", frontend), "utf8"),
  ]);
  return assembleAudioWorklet(prelude, bindgenGlue, processor);
}

async function main() {
  const expected = await expectedAudioWorkletBundle();
  if (process.argv.includes("--check")) {
    const actual = await readFile(outputUrl, "utf8").catch(() => "");
    if (actual !== expected) {
      throw new Error("frontend/audio-worklet-bundle.js is missing or stale");
    }
    return;
  }
  await writeFile(outputUrl, expected);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  await main();
}
